const mapDbs = (serverConfig) => {
    return serverConfig.db_info.map(db => {

      return {
        json: {
          server_host: serverConfig.server,
          port: serverConfig.port,
          user: serverConfig.user,
          password: serverConfig.password,

          database: db.db,
          entorno: db.entorno,   
          channelId: db.channelId,
          country: db.country,
          timezone: timezones[db.country] || "UTC", 
          type: executionType 
        }
      };
    });
};

const dbsArg = mapDbs(serverSQL1);
const dbsCol = mapDbs(serverSQL2);
